func testProdutoSeriesSliceUpdateAll(t *testing.T) {
	t.Parallel()

	if len(produtoSerieAllColumns) == len(produtoSeriePrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &ProdutoSerie{}
	if err = randomize.Struct(seed, o, produtoSerieDBTypes, true, produtoSerieColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ProdutoSerie struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := ProdutoSeries().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, produtoSerieDBTypes, true, produtoSeriePrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize ProdutoSerie struct: %s", err)
	}

	// Remove Primary keys and unique columns from what we plan to update
	var fields []string
	if strmangle.StringSliceMatch(produtoSerieAllColumns, produtoSeriePrimaryKeyColumns) {
		fields = produtoSerieAllColumns
	} else {
		fields = strmangle.SetComplement(
			produtoSerieAllColumns,
			produtoSeriePrimaryKeyColumns,
		)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	typ := reflect.TypeOf(o).Elem()
	n := typ.NumField()

	updateMap := M{}
	for _, col := range fields {
		for i := 0; i < n; i++ {
			f := typ.Field(i)
			if f.Tag.Get("boil") == col {
				updateMap[col] = value.Field(i).Interface()
			}
		}
	}

	slice := ProdutoSerieSlice{o}
	if rowsAff, err := slice.UpdateAll(ctx, tx, updateMap); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("wanted one record updated but got", rowsAff)
	}
}

